import{_ as o,o as e,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"请描述如何使用 ES6 的模块系统","description":"使用 ES6 的模块系统可以让开发者更方便地组织和管理 JavaScript 代码，支持模块化开发，从而提高代码的可维护性和可读性。以下是关于如何使用 ES6 模块系统的详细说明。 基本语法 ES6 模块系统引入了两个新的关键字： export 和 import 。 1. 导出模。","frontmatter":{"title":"请描述如何使用 ES6 的模块系统","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"使用 ES6 的模块系统可以让开发者更方便地组织和管理 JavaScript 代码，支持模块化开发，从而提高代码的可维护性和可读性。以下是关于如何使用 ES6 模块系统的详细说明。 基本语法 ES6 模块系统引入了两个新的关键字： export 和 import 。 1. 导出模。","sidebarWeight":54,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/请描述如何使用 ES6 的模块系统.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/请描述如何使用 ES6 的模块系统.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/请描述如何使用 ES6 的模块系统.md"}'),s={name:"posts/JavaScript系统教程/06-模块化与工程化/请描述如何使用 ES6 的模块系统.md"};function p(d,t,i,l,n,c){return e(),a("div",null,[...t[0]||(t[0]=[r('<div><h1 id="请描述如何使用-es6-的模块系统" tabindex="-1">请描述如何使用 ES6 的模块系统 <a class="header-anchor" href="#请描述如何使用-es6-的模块系统" aria-label="Permalink to &quot;请描述如何使用 ES6 的模块系统&quot;">​</a></h1><blockquote><p>本节目标：理解“请描述如何使用 ES6 的模块系统”的核心思路，并能把它用于实际开发或面试表达。 使用 ES6 的模块系统可以让开发者更方便地组织和管理 JavaScript 代码，支持模块化开发，从而提高代码的可维护性和可读性。以下是关于如何使用 ES6 模块系统的详细说明。</p></blockquote><h3 id="基本语法" tabindex="-1">基本语法 <a class="header-anchor" href="#基本语法" aria-label="Permalink to &quot;基本语法&quot;">​</a></h3><p>ES6 模块系统引入了两个新的关键字：<code>export</code> 和 <code>import</code>。</p><h4 id="_1-导出模块-export" tabindex="-1">1. 导出模块（Export） <a class="header-anchor" href="#_1-导出模块-export" aria-label="Permalink to &quot;1. 导出模块（Export）&quot;">​</a></h4><p>模块中的任何变量、函数或类都可以通过 <code>export</code> 关键字导出。</p><p><strong>命名导出（Named Export）</strong>： 命名导出允许在一个模块中导出多个值。 // math.js export const pi = 3.14159; export function add(x, y) { return x + y; }</p><p><strong>默认导出（Default Export）</strong>： 默认导出是指一个模块中只能有一个默认导出。 // math.js const pi = 3.14159; export default pi;</p><h4 id="_2-导入模块-import" tabindex="-1">2. 导入模块（Import） <a class="header-anchor" href="#_2-导入模块-import" aria-label="Permalink to &quot;2. 导入模块（Import）&quot;">​</a></h4><p>通过 <code>import</code> 关键字可以引入其他模块导出的变量、函数或类。</p><p><strong>导入命名导出</strong>： // main.js import { pi, add } from &#39;./math.js&#39;; console.log(pi); // 3.14159 console.log(add(2, 3)); // 5</p><p><strong>导入默认导出</strong>： // main.js import pi from &#39;./math.js&#39;; console.log(pi); // 3.14159</p><p><strong>导入所有导出</strong>： 可以使用 <code>* as</code> 语法将模块中的所有导出导入为一个命名空间对象。 // main.js import * as math from &#39;./math.js&#39;; console.log(math.pi); // 3.14159 console.log(math.add(2, 3)); // 5</p><h3 id="使用-es6-模块的实际场景" tabindex="-1">使用 ES6 模块的实际场景 <a class="header-anchor" href="#使用-es6-模块的实际场景" aria-label="Permalink to &quot;使用 ES6 模块的实际场景&quot;">​</a></h3><h4 id="_1-在浏览器中使用模块" tabindex="-1">1. 在浏览器中使用模块 <a class="header-anchor" href="#_1-在浏览器中使用模块" aria-label="Permalink to &quot;1. 在浏览器中使用模块&quot;">​</a></h4><p>现代浏览器已经原生支持 ES6 模块，只需要在 HTML 文件中使用 <code>type=&quot;module&quot;</code>。 &lt;!DOCTYPE html&gt; &lt;html lang=&quot;en&quot;&gt; &lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;title&gt;ES6 Modules&lt;/title&gt; &lt;script type=&quot;module&quot; src=&quot;main.js&quot;&gt;&lt;/script&gt; &lt;/head&gt; &lt;body&gt; &lt;/body&gt; &lt;/html&gt;</p><h4 id="_2-在-node-js-中使用模块" tabindex="-1">2. 在 Node.js 中使用模块 <a class="header-anchor" href="#_2-在-node-js-中使用模块" aria-label="Permalink to &quot;2. 在 Node.js 中使用模块&quot;">​</a></h4><p>Node.js 从 v12.17.0 开始支持 ES6 模块，需要将文件扩展名设置为 <code>.mjs</code>，或者在 <code>package.json</code> 中添加 <code>&quot;type&quot;: &quot;module&quot;</code>。 // package.json { &quot;type&quot;: &quot;module&quot; }</p><p>然后可以使用标准的 ES6 模块语法。 // math.mjs export const pi = 3.14159; export function add(x, y) { return x + y; } // main.mjs import { pi, add } from &#39;./math.mjs&#39;; console.log(pi); // 3.14159 console.log(add(2, 3)); // 5</p></div>',1)])])}const u=o(s,[["render",p]]);export{h as __pageData,u as default};
